{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "intro_text",
        "context_section",
        "prep_section",
        "install_section",
        "post_install_section",
        "quick_actions_section",
        "sources_section"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Ubuntu 22.04 LTS Clean Installation Guide",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This guide outlines the process for performing a clean installation of Ubuntu 22.04 LTS, replacing an existing Windows 11 installation on your primary drive, while ensuring data on a separate, secondary drive remains untouched."
      },
      "children": []
    },
    "context_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "context_title",
        "context_body1",
        "context_body2"
      ]
    },
    "context_title": {
      "type": "Text",
      "props": {
        "text": "Understanding the Installation",
        "variant": "h2"
      },
      "children": []
    },
    "context_body1": {
      "type": "Text",
      "props": {
        "text": "Ubuntu 22.04 LTS (Jammy Jellyfish) is a Long Term Support release, meaning it receives updates and support for five years."
      },
      "children": []
    },
    "context_body2": {
      "type": "Text",
      "props": {
        "text": "A clean installation ensures a fresh start, free from previous system issues or conflicts. This guide specifically addresses replacing Windows 11 on your primary drive (e.g., C: drive) while leaving a secondary data drive (e.g., D: drive) untouched."
      },
      "children": []
    },
    "prep_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "prep_title",
        "prep_card1",
        "prep_card2",
        "prep_card3"
      ]
    },
    "prep_title": {
      "type": "Text",
      "props": {
        "text": "Preparation Steps",
        "variant": "h2"
      },
      "children": []
    },
    "prep_card1": {
      "type": "Card",
      "props": {},
      "children": [
        "prep_card1_title",
        "prep_card1_text"
      ]
    },
    "prep_card1_title": {
      "type": "Text",
      "props": {
        "text": "1. Backup Your Data",
        "variant": "h3"
      },
      "children": []
    },
    "prep_card1_text": {
      "type": "Text",
      "props": {
        "text": "Crucial: The primary drive will be completely erased. Ensure all important files from your Windows 11 installation are backed up to an external drive or cloud storage."
      },
      "children": []
    },
    "prep_card2": {
      "type": "Card",
      "props": {},
      "children": [
        "prep_card2_title",
        "prep_card2_text1",
        "prep_card2_text2"
      ]
    },
    "prep_card2_title": {
      "type": "Text",
      "props": {
        "text": "2. Create a Bootable Ubuntu USB Drive",
        "variant": "h3"
      },
      "children": []
    },
    "prep_card2_text1": {
      "type": "Text",
      "props": {
        "text": "Download the Ubuntu 22.04 LTS ISO image from the official Ubuntu website."
      },
      "children": []
    },
    "prep_card2_text2": {
      "type": "Text",
      "props": {
        "text": "Use a tool like Rufus (Windows) or Etcher (cross-platform) to write the ISO image to a USB drive (minimum 8GB)."
      },
      "children": []
    },
    "prep_card3": {
      "type": "Card",
      "props": {},
      "children": [
        "prep_card3_title",
        "prep_card3_text1",
        "prep_card3_text2",
        "prep_card3_text3"
      ]
    },
    "prep_card3_title": {
      "type": "Text",
      "props": {
        "text": "3. Adjust BIOS/UEFI Settings",
        "variant": "h3"
      },
      "children": []
    },
    "prep_card3_text1": {
      "type": "Text",
      "props": {
        "text": "Disable 'Fast Startup' in Windows Power Options before rebooting."
      },
      "children": []
    },
    "prep_card3_text2": {
      "type": "Text",
      "props": {
        "text": "Access your computer's BIOS/UEFI settings (usually by pressing F2, F10, F12, or Del during startup) and disable 'Secure Boot' and 'Fast Boot'."
      },
      "children": []
    },
    "prep_card3_text3": {
      "type": "Text",
      "props": {
        "text": "Set your USB drive as the primary boot device or use the boot menu to select it."
      },
      "children": []
    },
    "install_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "install_title",
        "install_card1",
        "install_card2",
        "install_card3",
        "install_card4"
      ]
    },
    "install_title": {
      "type": "Text",
      "props": {
        "text": "Installation Process",
        "variant": "h2"
      },
      "children": []
    },
    "install_card1": {
      "type": "Card",
      "props": {},
      "children": [
        "install_card1_title",
        "install_card1_text"
      ]
    },
    "install_card1_title": {
      "type": "Text",
      "props": {
        "text": "1. Boot from USB",
        "variant": "h3"
      },
      "children": []
    },
    "install_card1_text": {
      "type": "Text",
      "props": {
        "text": "Restart your computer and boot from the Ubuntu USB drive. You should see the Ubuntu GRUB menu or a 'Try or Install Ubuntu' screen."
      },
      "children": []
    },
    "install_card2": {
      "type": "Card",
      "props": {},
      "children": [
        "install_card2_title",
        "install_card2_text1",
        "install_card2_text2",
        "install_card2_text3"
      ]
    },
    "install_card2_title": {
      "type": "Text",
      "props": {
        "text": "2. Select Language and Installation Type",
        "variant": "h3"
      },
      "children": []
    },
    "install_card2_text1": {
      "type": "Text",
      "props": {
        "text": "Choose your preferred language."
      },
      "children": []
    },
    "install_card2_text2": {
      "type": "Text",
      "props": {
        "text": "Select 'Install Ubuntu'."
      },
      "children": []
    },
    "install_card2_text3": {
      "type": "Text",
      "props": {
        "text": "On the 'Installation type' screen, choose 'Erase disk and install Ubuntu'. Carefully select your primary drive (the one Windows 11 was on). This will wipe the selected drive. Your secondary drive should not be affected if you do not select it."
      },
      "children": []
    },
    "install_card3": {
      "type": "Card",
      "props": {},
      "children": [
        "install_card3_title",
        "install_card3_text"
      ]
    },
    "install_card3_title": {
      "type": "Text",
      "props": {
        "text": "3. Configure User and Location",
        "variant": "h3"
      },
      "children": []
    },
    "install_card3_text": {
      "type": "Text",
      "props": {
        "text": "Follow the prompts to set your timezone, keyboard layout, and create your user account (username, password, computer name)."
      },
      "children": []
    },
    "install_card4": {
      "type": "Card",
      "props": {},
      "children": [
        "install_card4_title",
        "install_card4_text"
      ]
    },
    "install_card4_title": {
      "type": "Text",
      "props": {
        "text": "4. Installation Completion",
        "variant": "h3"
      },
      "children": []
    },
    "install_card4_text": {
      "type": "Text",
      "props": {
        "text": "Once the installation is complete, you will be prompted to restart your computer. Remove the USB drive when instructed."
      },
      "children": []
    },
    "post_install_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "post_install_title",
        "post_install_card1",
        "post_install_card2",
        "post_install_card3"
      ]
    },
    "post_install_title": {
      "type": "Text",
      "props": {
        "text": "Post-Installation Steps",
        "variant": "h2"
      },
      "children": []
    },
    "post_install_card1": {
      "type": "Card",
      "props": {},
      "children": [
        "post_install_card1_title",
        "post_install_card1_text",
        "post_install_card1_code"
      ]
    },
    "post_install_card1_title": {
      "type": "Text",
      "props": {
        "text": "1. Update Your System",
        "variant": "h3"
      },
      "children": []
    },
    "post_install_card1_text": {
      "type": "Text",
      "props": {
        "text": "Open a terminal (Ctrl+Alt+T) and run the following commands:"
      },
      "children": []
    },
    "post_install_card1_code": {
      "type": "ConsoleLog",
      "props": {
        "code": "sudo apt update && sudo apt upgrade -y",
        "language": "console"
      },
      "children": []
    },
    "post_install_card2": {
      "type": "Card",
      "props": {},
      "children": [
        "post_install_card2_title",
        "post_install_card2_text"
      ]
    },
    "post_install_card2_title": {
      "type": "Text",
      "props": {
        "text": "2. Install Additional Drivers",
        "variant": "h3"
      },
      "children": []
    },
    "post_install_card2_text": {
      "type": "Text",
      "props": {
        "text": "Go to 'Software & Updates' -> 'Additional Drivers' tab to install proprietary drivers (e.g., for graphics cards)."
      },
      "children": []
    },
    "post_install_card3": {
      "type": "Card",
      "props": {},
      "children": [
        "post_install_card3_title",
        "post_install_card3_text"
      ]
    },
    "post_install_card3_title": {
      "type": "Text",
      "props": {
        "text": "3. Install Essential Software",
        "variant": "h3"
      },
      "children": []
    },
    "post_install_card3_text": {
      "type": "Text",
      "props": {
        "text": "Install your preferred applications using the Ubuntu Software Center or the command line (e.g., `sudo apt install <package_name>`)."
      },
      "children": []
    },
    "quick_actions_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "quick_actions_title",
        "ubuntu_download_button",
        "ubuntu_docs_button"
      ]
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "ubuntu_download_button": {
      "type": "Button",
      "props": {
        "label": "Download Ubuntu 22.04 LTS"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://ubuntu.com/download/desktop"
          }
        }
      },
      "children": []
    },
    "ubuntu_docs_button": {
      "type": "Button",
      "props": {
        "label": "Ubuntu Documentation"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://ubuntu.com/tutorials/install-ubuntu-desktop"
          }
        }
      },
      "children": []
    },
    "sources_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "sources_title",
        "source1_stack",
        "source2_stack"
      ]
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "source1_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "source1_text",
        "source1_button"
      ]
    },
    "source1_text": {
      "type": "Text",
      "props": {
        "text": "Official Ubuntu Website:"
      },
      "children": []
    },
    "source1_button": {
      "type": "Button",
      "props": {
        "label": "ubuntu.com",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://ubuntu.com/"
          }
        }
      },
      "children": []
    },
    "source2_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "source2_text",
        "source2_button"
      ]
    },
    "source2_text": {
      "type": "Text",
      "props": {
        "text": "Ubuntu 22.04 LTS Release Notes:"
      },
      "children": []
    },
    "source2_button": {
      "type": "Button",
      "props": {
        "label": "Release Notes",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://ubuntu.com/blog/ubuntu-22-04-lts-released"
          }
        }
      },
      "children": []
    }
  }
}
